% ============================================================
%   SOFT VOTING ENSEMBLE CLASSIFICATION
%   Combines multiple models from Classification Learner
%   using probability averaging (Soft Voting).
% ============================================================

clc; close all;

%% 1. Load Validation Data
% This should be the table generated by MonteCarloPatients.m
data_file = 'Data/MonteCarloPatients_with_Features.csv';
if isfile(data_file)
    X_test = readtable(data_file);
else
    error('Validation data not found. Run MonteCarloPatients.m first.');
end

%% 2. Define Models and their Accuracies
% Assume you have exported these from Classification Learner.
% List your models and their known validation accuracies (from the App).

% List your models here
models = {LH_No_WideNet, LH_No_FineSVM, LH_No_EnsembleTree}; 

% Accuracy weights for each model (e.g. 0.98 for 98%)
% These should be the validation accuracies from the Classification Learner App.
weights = [0.805, 0.799, 0.793]; 

num_models = numel(models);
if numel(weights) ~= num_models
    error('The number of weights must match the number of models.');
end

num_samples = height(X_test);
fprintf('Weighted Soft Voting with %d models...\n', num_models);

%% 3. Collect Weighted Probability Scores
% Initialize score accumulator (NumSamples x NumClasses)
[~, first_scores] = models{1}.predictFcn(X_test);
num_classes = size(first_scores, 2);
total_weighted_scores = zeros(num_samples, num_classes);

for i = 1:num_models
    [~, scores] = models{i}.predictFcn(X_test);
    
    % Multiply model probability row by its accuracy weight
    weighted_row = weights(i) * scores;
    
    % Accumulate weighted scores
    total_weighted_scores = total_weighted_scores + weighted_row;
end

% Final Weighted Average
% Dividing by sum(weights) ensures the final probabilities add up to 1.0
avg_scores = total_weighted_scores / sum(weights);

%% 4. Determine Final Predictions
[~, class_idx] = max(avg_scores, [], 2);

% Map indices to original class names
% Note: Classification Learner models store class names in different places depending on version
if isfield(models{1}, 'ClassificationModel')
    class_names = models{1}.ClassificationModel.ClassNames;
else
    % Fallback if it's a simple categorical or numeric list
    class_names = [0, 1, 2]; 
end

y_final_pred = class_names(class_idx);
y_final_pred = y_final_pred(:); % Force to column vector

%% 5. Evaluate Performance
if ismember('Condition', X_test.Properties.VariableNames)
    y_true = X_test.Condition;
    accuracy = mean(y_final_pred == y_true) * 100;
    
    fprintf('\n=== Ensemble Results ===\n');
    fprintf('Final Ensemble Accuracy: %.2f%%\n', accuracy);
    
    % Display Confusion Matrix
    figure('Name', 'Ensemble Confusion Matrix', 'Color', 'w');
    confusionchart(y_true, y_final_pred, 'Title', 'Soft Voting Ensemble Performance');
else
    fprintf('\nPredictions complete. (No ground truth found in data for accuracy check).\n');
end

% Display some results
disp('First 10 Ensemble Predictions:');
disp(table(y_true(1:10), y_final_pred(1:10), 'VariableNames', {'True', 'Predicted'}));

